package com.citacloud.springboot.contacloud.app.models;import org.junit.jupiter.api.Test;import java.lang.reflect.Field;import java.math.BigDecimal;import java.time.LocalDate;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
class AjusteInventarioTest{
 @Test void confirmaBorradorYCapturaContextoHistorico(){UUID u=UUID.randomUUID();Almacen w=warehouse();MotivoAjusteInventario m=reason();AjusteInventario a=new AjusteInventario(UUID.randomUUID(),UUID.randomUUID(),"AJU-000001",LocalDate.of(2026,10,13),w,m,null,null,TipoAjusteInventario.MIXED,u);a.confirmar(u,"María López");assertThat(a.getEstado()).isEqualTo(EstadoAjusteInventario.CONFIRMED);assertThat(a.getAlmacenHistorico()).isEqualTo("Almacén Principal");assertThat(a.getSucursalHistorica()).isEqualTo("Sucursal Principal");assertThat(a.getMotivoHistorico()).isEqualTo("Corrección de inventario");assertThat(a.getConfirmadaPorNombre()).isEqualTo("María López");}
 @Test void confirmadoNoPuedeEditar(){UUID u=UUID.randomUUID();Almacen w=warehouse();MotivoAjusteInventario m=reason();AjusteInventario a=new AjusteInventario(UUID.randomUUID(),UUID.randomUUID(),"AJU-000001",LocalDate.now(),w,m,null,null,TipoAjusteInventario.ENTRY,u);a.confirmar(u,"Admin");assertThatThrownBy(()->a.actualizar(LocalDate.now(),w,m,null,null,TipoAjusteInventario.EXIT,u)).hasMessage("Solo se puede modificar un ajuste en borrador.");}
 @Test void lineaConservaSnapshotsYSaldos(){UUID t=UUID.randomUUID(),e=UUID.randomUUID(),u=UUID.randomUUID();AjusteInventario a=new AjusteInventario(t,e,"AJU-000001",LocalDate.now(),warehouse(),reason(),null,null,TipoAjusteInventario.EXIT,u);set(a,"id",UUID.randomUUID());UUID unit=UUID.randomUUID();Producto p=new Producto(t,e,"PRD-000001","Laptop",TipoProducto.PRODUCT,null,unit,null,null,null,null,null,null,null,true,false,null,true,u);set(p,"id",UUID.randomUUID());LineaAjusteInventario l=new LineaAjusteInventario(a,p,new BigDecimal("-2"),1);l.capturarSaldos(new BigDecimal("25"),new BigDecimal("23"));assertThat(l.getCantidadAjuste()).isEqualByComparingTo("-2");assertThat(l.getSaldoAnterior()).isEqualByComparingTo("25");assertThat(l.getSaldoPosterior()).isEqualByComparingTo("23");assertThatThrownBy(()->l.capturarSaldos(BigDecimal.ONE,BigDecimal.TEN)).hasMessage("Los saldos históricos ya fueron registrados.");}
 private static Almacen warehouse(){UUID e=UUID.randomUUID(),u=UUID.randomUUID();Sucursal s=new Sucursal(e,"PRI","Sucursal Principal");set(s,"id",UUID.randomUUID());Almacen w=new Almacen(UUID.randomUUID(),e,"ALM-01","Almacén Principal","almacén principal",s.getId(),TipoAlmacen.GENERAL,null,null,null,u);set(w,"id",UUID.randomUUID());w.asignarReferencias(s,null);return w;}private static MotivoAjusteInventario reason(){MotivoAjusteInventario m=new MotivoAjusteInventario();set(m,"id",UUID.randomUUID());set(m,"name","Corrección de inventario");return m;}private static void set(Object target,String name,Object value){try{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);f.set(target,value);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
}
